// Minimal URL parser + validator

#[derive(Debug, Clone)]
pub struct Url {
    pub scheme: String,
    pub userinfo: Option<(String, String)>, // (user, password)
    pub host: String,
    pub port: Option<u16>,
    pub path: String, // starts with '/'
    pub query: String,
    pub fragment: String,
}

pub fn parse(s: &str) -> Result<Url, String> {
    if s.is_empty() {
        return Err("relative URL without a base".to_string());
    }
    // find scheme
    let scheme_end = match s.find("://") {
        Some(i) => i,
        None => return Err("relative URL without a base".to_string()),
    };
    let scheme = s[..scheme_end].to_ascii_lowercase();
    if scheme.is_empty() {
        return Err("relative URL without a base".to_string());
    }
    for c in scheme.chars() {
        if !c.is_ascii_alphanumeric() && c != '+' && c != '-' && c != '.' {
            return Err("relative URL without a base".to_string());
        }
    }
    let rest = &s[scheme_end + 3..];

    // split path/query/fragment
    let (authority, path_part) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, ""),
    };

    let (userinfo, hostport) = match authority.rfind('@') {
        Some(i) => {
            let up = &authority[..i];
            let (u, p) = match up.find(':') {
                Some(j) => (up[..j].to_string(), up[j+1..].to_string()),
                None => (up.to_string(), String::new()),
            };
            (Some((u, p)), &authority[i+1..])
        }
        None => (None, authority),
    };

    let (host, port) = if let Some(i) = hostport.rfind(':') {
        // make sure the : is not part of IPv6
        let after = &hostport[i+1..];
        if !after.is_empty() {
            match after.parse::<u16>() {
                Ok(p) => (hostport[..i].to_string(), Some(p)),
                Err(_) => {
                    if hostport.starts_with('[') {
                        (hostport.to_string(), None)
                    } else {
                        return Err("invalid port number".to_string());
                    }
                }
            }
        } else {
            (hostport[..i].to_string(), None)
        }
    } else {
        (hostport.to_string(), None)
    };

    if host.is_empty() {
        return Err("empty host".to_string());
    }

    let path_and_rest = if path_part.is_empty() { "/".to_string() } else { path_part.to_string() };
    let (pp, fragment) = match path_and_rest.find('#') {
        Some(i) => (path_and_rest[..i].to_string(), path_and_rest[i+1..].to_string()),
        None => (path_and_rest, String::new()),
    };
    let (path, query) = match pp.find('?') {
        Some(i) => (pp[..i].to_string(), pp[i+1..].to_string()),
        None => (pp, String::new()),
    };

    Ok(Url {
        scheme,
        userinfo,
        host,
        port,
        path,
        query,
        fragment,
    })
}

impl Url {
    pub fn port_or_default(&self) -> u16 {
        match self.port {
            Some(p) => p,
            None => match self.scheme.as_str() {
                "https" => 443,
                "http" => 80,
                _ => 80,
            },
        }
    }

    pub fn host_header(&self) -> String {
        match self.port {
            Some(p) => format!("{}:{}", self.host, p),
            None => self.host.clone(),
        }
    }

    pub fn base(&self) -> String {
        let mut s = format!("{}://{}", self.scheme, self.host);
        if let Some(p) = self.port {
            s.push_str(&format!(":{}", p));
        }
        s
    }

    // Returns url string but normalized with trailing '/' on path if needed
    pub fn to_string_with_trailing_slash(&self) -> String {
        let mut s = self.base();
        let mut p = self.path.clone();
        if !p.ends_with('/') {
            p.push('/');
        }
        s.push_str(&p);
        s
    }

    pub fn to_string_norm(&self) -> String {
        // Normalize: if the original path was empty, it becomes "/"
        let mut s = self.base();
        if self.path.is_empty() {
            s.push('/');
        } else {
            s.push_str(&self.path);
        }
        s
    }
}
