// Option descriptor
#[derive(Debug, Clone)]
struct OptSpec {
    long: &'static str,       // e.g. "uri"
    short: Option<char>,      // e.g. Some('u')
    aliases: &'static [&'static str],
    value_name: Option<&'static str>,
    takes_value: bool,
    multi: bool,              // accumulates values
    variadic: bool,           // --multi a b c; default false (single value per occurrence)
    // For error: value_hint like "<uri>"
}

