// Render argument spec for error messages
fn render_arg_decl(spec: &OptSpec) -> String {
    if let Some(vn) = spec.value_name {
        if spec.variadic {
            format!("--{} <{}>...", spec.long, vn)
        } else {
            format!("--{} <{}>", spec.long, vn)
        }
    } else {
        if spec.long == "verbose" {
            "--verbose...".to_string()
        } else {
            format!("--{}", spec.long)
        }
    }
}

fn usage_required_hint(order: &[&str], specs_map: &HashMap<String, OptSpec>) -> String {
    // Called for "Usage: ..." when required arguments were used
    let mut parts = Vec::new();
    for s in order {
        if let Some(spec) = specs_map.get(*s) {
            parts.push(format!("--{} <{}>", spec.long, spec.value_name.unwrap_or("")));
        }
    }
    parts.push("<uri|--uri-file <uri-file>|--uri <uri>>".to_string());
    format!("Usage: executable {}\n", parts.join(" "))
}

fn usage_line() -> String {
    "Usage: executable [OPTIONS] <uri|--uri-file <uri-file>|--uri <uri>>\n".to_string()
}

fn err_footer(extra_usage: Option<String>) -> String {
    let mut s = String::new();
    s.push('\n');
    if let Some(u) = extra_usage { s.push_str(&u); s.push('\n'); } else { s.push_str(&usage_line()); s.push('\n'); }
    s.push_str("For more information, try '--help'.\n");
    s
}

pub fn parse(argv: &[String]) -> ParseResult {
    if argv.len() <= 1 {
        return ParseResult::NoArgs;
    }

    let spec_list = specs();
    // Map long & aliases to spec index
    let mut by_long: HashMap<String, usize> = HashMap::new();
    let mut by_short: HashMap<char, usize> = HashMap::new();
    let mut specs_map: HashMap<String, OptSpec> = HashMap::new();
    for (i, s) in spec_list.iter().enumerate() {
        by_long.insert(s.long.to_string(), i);
        for a in s.aliases { by_long.insert(a.to_string(), i); }
        if let Some(sh) = s.short { by_short.insert(sh, i); }
        specs_map.insert(s.long.to_string(), s.clone());
    }

    // First pass: detect help/version anywhere (clap does this before validation errors)
    // Actually clap prints version if -V is present and no earlier parse error.
    // We will do a single pass but watch for -h and -V triggers.

    let mut cfg = Config::new();
    let mut i = 1;
    let mut positional_taken = false;
    let mut only_positional = false;
    // Track which options with required values were successfully parsed (for "required args" msg)
    let mut uris_provided = false; // -u/--uri/--uri-file or positional

    // Track last --verb, etc. — clap overwrites
    let mut help_requested = false;
    let mut version_requested = false;
    let mut silent_set = false;
    let mut verbose_set = false;

    // Need to keep track of errors but still process -V/-h
    // Simpler approach: scan args first for -h or -V (not after --)
    let mut scan_i = 1;
    let mut ended = false;
    while scan_i < argv.len() {
        let a = &argv[scan_i];
        if a == "--" { ended = true; break; }
        if !ended {
            if a == "-h" || a == "--help" { help_requested = true; break; }
            if a == "-V" || a == "--version" { version_requested = true; break; }
            if a.starts_with("--") && a.len() > 2 && a[2..].contains('=') {
                // ignored
            } else if a.starts_with('-') && !a.starts_with("--") && a.len() > 1 {
                // check short bundle for h or V
                let chars: Vec<char> = a[1..].chars().collect();
                for (ci, c) in chars.iter().enumerate() {
                    if *c == 'h' { help_requested = true; break; }
                    if *c == 'V' { version_requested = true; break; }
                    // if short char takes value, stop scanning
                    if let Some(&idx) = by_short.get(c) {
                        if spec_list[idx].takes_value {
                            // consume rest as value
                            let _ = ci;
                            break;
                        }
                    } else {
                        break;
                    }
                }
                if help_requested || version_requested { break; }
            }
        }
        scan_i += 1;
    }
    if help_requested {
        return ParseResult::Help;
    }
    if version_requested {
        return ParseResult::Version;
    }

    // Order map for required-args error messages. This is determined by positional order of args in help
    // (json-file, xml-file, output-all, output-file, wordlist)
    // Actually let's compute it dynamically by tracking which required-provided flags are used.

    // Main parse
    let mut provided_required: Vec<String> = Vec::new(); // long names of required provided
    let mut errors: Vec<String> = Vec::new();
    let mut bool_short_names: std::collections::HashSet<&'static str> = std::collections::HashSet::new();

    while i < argv.len() {
        let a = argv[i].clone();
        i += 1;

        if a == "--" { only_positional = true; continue; }

        if !only_positional && a.starts_with("--") {
            // Long option
            let body = &a[2..];
            let (name, value) = match body.find('=') {
                Some(p) => (body[..p].to_string(), Some(body[p+1..].to_string())),
                None => (body.to_string(), None),
            };
            let idx = match by_long.get(&name) {
                Some(&i) => i,
                None => {
                    return ParseResult::Error(unexpected_long_error(&a));
                }
            };
            let spec = &spec_list[idx];
            if spec.takes_value {
                let v = if let Some(v) = value {
                    v
                } else {
                    if i < argv.len() {
                        let nv = argv[i].clone();
                        i += 1;
                        nv
                    } else {
                        return ParseResult::Error(missing_value_error(spec));
                    }
                };
                // If variadic, try to collect more values until next option or positional
                let mut vals = vec![v];
                if spec.variadic {
                    while i < argv.len() {
                        let peek = &argv[i];
                        if peek == "--" { break; }
                        if peek.starts_with('-') && peek.len() > 1 {
                            break;
                        }
                        vals.push(argv[i].clone());
                        i += 1;
                    }
                }
                match apply_option_long(spec, &vals, &mut cfg) {
                    Ok(_) => {
                        provided_required.push(spec.long.to_string());
                    }
                    Err(msg) => return ParseResult::Error(msg),
                }
                if spec.long == "uri" { uris_provided = true; }
                if spec.long == "uri-file" { uris_provided = true; }
                if spec.long == "silent" { silent_set = true; }
                if spec.long == "verbose" { verbose_set = true; }
            } else {
                // boolean flag
                if let Some(_v) = value {
                    // --flag=value where flag takes no value
                    return ParseResult::Error(format!("error: unexpected value '{}' for '{}' found; no more were expected\n\n{}\nFor more information, try '--help'.\n", _v, render_arg_decl(spec), usage_line()));
                }
                apply_bool_long(spec, &mut cfg);
                if spec.long == "silent" { silent_set = true; }
                if spec.long == "verbose" { verbose_set = true; }
                bool_short_names.insert(spec.long);
            }
            continue;
        }

        if !only_positional && a.starts_with('-') && a.len() > 1 && !a.starts_with("--") {
            // Short bundle: -x, -xval, -xvval, -kS
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let idx = match by_short.get(&c) {
                    Some(&i) => i,
                    None => {
                        let dashed = format!("-{}", c);
                        return ParseResult::Error(unexpected_short_error(&dashed));
                    }
                };
                let spec = &spec_list[idx];
                if spec.takes_value {
                    // value is rest of this arg (possibly with leading '=') or next arg
                    let rest: String = chars[ci+1..].iter().collect();
                    let v = if rest.is_empty() {
                        if i < argv.len() {
                            let nv = argv[i].clone();
                            i += 1;
                            nv
                        } else {
                            return ParseResult::Error(missing_value_error(spec));
                        }
                    } else if rest.starts_with('=') {
                        rest[1..].to_string()
                    } else {
                        rest
                    };
                    let mut vals = vec![v];
                    if spec.variadic {
                        while i < argv.len() {
                            let peek = &argv[i];
                            if peek == "--" { break; }
                            if peek.starts_with('-') && peek.len() > 1 {
                                break;
                            }
                            vals.push(argv[i].clone());
                            i += 1;
                        }
                    }
                    match apply_option_long(spec, &vals, &mut cfg) {
                        Ok(_) => { provided_required.push(spec.long.to_string()); }
                        Err(msg) => return ParseResult::Error(msg),
                    }
                    if spec.long == "uri" { uris_provided = true; }
                    if spec.long == "uri-file" { uris_provided = true; }
                    break;
                } else {
                    apply_bool_long(spec, &mut cfg);
                    if spec.long == "silent" { silent_set = true; }
                    if spec.long == "verbose" { verbose_set = true; }
                    ci += 1;
                }
            }
            continue;
        }

        // Positional
        if positional_taken {
            return ParseResult::Error(unexpected_positional_error(&a));
        }
        // Validate URI
        match crate::url::parse(&a) {
            Ok(_) => {},
            Err(msg) => {
                return ParseResult::Error(invalid_value_error("[uri]", &a, &msg));
            }
        }
        cfg.uri_positional = Some(a);
        positional_taken = true;
        uris_provided = true;
    }

    // Check silent/verbose conflict
    if silent_set && verbose_set {
        return ParseResult::Error(conflict_error("--silent", "--verbose...", "--silent"));
    }

    if !uris_provided {
        return ParseResult::Error(required_args_error(&provided_required, &specs_map));
    }

    // Apply burp proxy default
    if cfg.burp && cfg.proxy.is_none() {
        cfg.proxy = Some("http://localhost:8080".to_string());
    }

    ParseResult::Ok(cfg)
}

fn unexpected_long_error(arg: &str) -> String {
    let raw_name = arg.split('=').next().unwrap_or(arg).to_string();
    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
        raw_name, raw_name, raw_name, usage_line())
}

fn unexpected_short_error(arg: &str) -> String {
    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
        arg, arg, arg, usage_line())
}

fn unexpected_positional_error(arg: &str) -> String {
    format!("error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
        arg, usage_line())
}

fn missing_value_error(spec: &OptSpec) -> String {
    format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n", render_arg_decl(spec))
}

fn invalid_value_error(arg_label: &str, val: &str, msg: &str) -> String {
    format!("error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n", val, arg_label, msg)
}

fn invalid_value_no_msg(arg_label: &str, val: &str, possible_values: &[&str]) -> String {
    let mut s = format!("error: invalid value '{}' for '{}'\n", val, arg_label);
    if !possible_values.is_empty() {
        s.push_str(&format!("  [possible values: {}]\n", possible_values.join(", ")));
    }
    s.push_str("\nFor more information, try '--help'.\n");
    s
}

fn conflict_error(a: &str, b: &str, required_arg_repr: &str) -> String {
    format!("error: the argument '{}' cannot be used with '{}'\n\nUsage: executable {} <uri|--uri-file <uri-file>|--uri <uri>>\n\nFor more information, try '--help'.\n",
        a, b, required_arg_repr)
}

fn required_args_error(provided: &[String], specs_map: &HashMap<String, OptSpec>) -> String {
    // Look up which required-that-provided-a-value flags are used, order: json-file, xml-file, output-all, output-file, wordlist
    let order = ["json-file","xml-file","output-all","output-file","wordlist"];
    let mut usage_parts = Vec::new();
    for name in order.iter() {
        if provided.contains(&name.to_string()) {
            if let Some(spec) = specs_map.get(&name.to_string()) {
                usage_parts.push(format!("--{} <{}>", spec.long, spec.value_name.unwrap_or("")));
            }
        }
    }
    let prefix = if usage_parts.is_empty() { "[OPTIONS]".to_string() } else { usage_parts.join(" ") };
    format!("error: the following required arguments were not provided:\n  <uri|--uri-file <uri-file>|--uri <uri>>\n\nUsage: executable {} <uri|--uri-file <uri-file>|--uri <uri>>\n\nFor more information, try '--help'.\n",
        prefix)
}

fn apply_option_long(spec: &OptSpec, vals: &[String], cfg: &mut Config) -> Result<(), String> {
    // The first value is the actual value; for variadic, additional values
    match spec.long {
        "uri" => {
            for v in vals {
                if let Err(e) = crate::url::parse(v) {
                    return Err(invalid_value_error("--uri <uri>", v, &e));
                }
                cfg.uris.push(v.clone());
            }
        }
        "uri-file" => { cfg.uri_file = Some(vals[0].clone()); }
        "verb" => {
            let v = vals[0].to_ascii_lowercase();
            match v.as_str() {
                "get" => cfg.verb = Verb::Get,
                "head" => cfg.verb = Verb::Head,
                "post" => cfg.verb = Verb::Post,
                _ => return Err(invalid_value_no_msg("--verb <http_verb>", &vals[0], &["get","head","post"])),
            }
        }
        "wordlist" => { cfg.wordlist = Some(vals[0].clone()); }
        "prefixes" => {
            for v in vals {
                for p in v.split(',') { cfg.prefixes.push(p.to_string()); }
            }
        }
        "prefix-file" => { cfg.prefix_file = Some(vals[0].clone()); }
        "extensions" => {
            for v in vals {
                for p in v.split(',') { cfg.extensions.push(p.to_string()); }
            }
        }
        "extension-file" => { cfg.extension_file = Some(vals[0].clone()); }
        "timeout" => {
            match vals[0].parse::<u32>() {
                Ok(v) => cfg.timeout = v,
