                    }
                    match apply_option_long(spec, &vals, &mut cfg) {
                        Ok(_) => { provided_required.push(spec.long.to_string()); }
                        Err(msg) => return ParseResult::Error(msg),
                    }
                    if spec.long == "uri" { uris_provided = true; }
                    if spec.long == "uri-file" { uris_provided = true; }
                    break;
                } else {
                    apply_bool_long(spec, &mut cfg);
                    if spec.long == "silent" { silent_set = true; }
                    if spec.long == "verbose" { verbose_set = true; }
                    ci += 1;
                }
            }
            continue;
        }

        // Positional
        if positional_taken {
            return ParseResult::Error(unexpected_positional_error(&a));
        }
        // Validate URI
        match crate::url::parse(&a) {
            Ok(_) => {},
            Err(msg) => {
                return ParseResult::Error(invalid_value_error("[uri]", &a, &msg));
            }
        }
        cfg.uri_positional = Some(a);
        positional_taken = true;
        uris_provided = true;
    }

    // Check silent/verbose conflict
    if silent_set && verbose_set {
        return ParseResult::Error(conflict_error("--silent", "--verbose...", "--silent"));
    }

    if !uris_provided {
        return ParseResult::Error(required_args_error(&provided_required, &specs_map));
    }

    // Apply burp proxy default
    if cfg.burp && cfg.proxy.is_none() {
        cfg.proxy = Some("http://localhost:8080".to_string());
    }

    ParseResult::Ok(cfg)
}

fn unexpected_long_error(arg: &str) -> String {
    let raw_name = arg.split('=').next().unwrap_or(arg).to_string();
    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
        raw_name, raw_name, raw_name, usage_line())
}

fn unexpected_short_error(arg: &str) -> String {
    format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\n{}\nFor more information, try '--help'.\n",
        arg, arg, arg, usage_line())
}

fn unexpected_positional_error(arg: &str) -> String {
    format!("error: unexpected argument '{}' found\n\n{}\nFor more information, try '--help'.\n",
        arg, usage_line())
}

fn missing_value_error(spec: &OptSpec) -> String {
    format!("error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n", render_arg_decl(spec))
}

fn invalid_value_error(arg_label: &str, val: &str, msg: &str) -> String {
    format!("error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n", val, arg_label, msg)
}

fn invalid_value_no_msg(arg_label: &str, val: &str, possible_values: &[&str]) -> String {
    let mut s = format!("error: invalid value '{}' for '{}'\n", val, arg_label);
    if !possible_values.is_empty() {
        s.push_str(&format!("  [possible values: {}]\n", possible_values.join(", ")));
    }
    s.push_str("\nFor more information, try '--help'.\n");
    s
}

fn conflict_error(a: &str, b: &str, required_arg_repr: &str) -> String {
    format!("error: the argument '{}' cannot be used with '{}'\n\nUsage: executable {} <uri|--uri-file <uri-file>|--uri <uri>>\n\nFor more information, try '--help'.\n",
        a, b, required_arg_repr)
}

fn required_args_error(provided: &[String], specs_map: &HashMap<String, OptSpec>) -> String {
    // Look up which required-that-provided-a-value flags are used, order: json-file, xml-file, output-all, output-file, wordlist
    let order = ["json-file","xml-file","output-all","output-file","wordlist"];
    let mut usage_parts = Vec::new();
    for name in order.iter() {
        if provided.contains(&name.to_string()) {
            if let Some(spec) = specs_map.get(&name.to_string()) {
                usage_parts.push(format!("--{} <{}>", spec.long, spec.value_name.unwrap_or("")));
            }
        }
    }
    let prefix = if usage_parts.is_empty() { "[OPTIONS]".to_string() } else { usage_parts.join(" ") };
    format!("error: the following required arguments were not provided:\n  <uri|--uri-file <uri-file>|--uri <uri>>\n\nUsage: executable {} <uri|--uri-file <uri-file>|--uri <uri>>\n\nFor more information, try '--help'.\n",
        prefix)
}

fn apply_option_long(spec: &OptSpec, vals: &[String], cfg: &mut Config) -> Result<(), String> {
    // The first value is the actual value; for variadic, additional values
    match spec.long {
        "uri" => {
            for v in vals {
                if let Err(e) = crate::url::parse(v) {
                    return Err(invalid_value_error("--uri <uri>", v, &e));
                }
                cfg.uris.push(v.clone());
            }
        }
        "uri-file" => { cfg.uri_file = Some(vals[0].clone()); }
        "verb" => {
            let v = vals[0].to_ascii_lowercase();
            match v.as_str() {
                "get" => cfg.verb = Verb::Get,
                "head" => cfg.verb = Verb::Head,
                "post" => cfg.verb = Verb::Post,
                _ => return Err(invalid_value_no_msg("--verb <http_verb>", &vals[0], &["get","head","post"])),
            }
        }
        "wordlist" => { cfg.wordlist = Some(vals[0].clone()); }
        "prefixes" => {
            for v in vals {
                for p in v.split(',') { cfg.prefixes.push(p.to_string()); }
            }
        }
        "prefix-file" => { cfg.prefix_file = Some(vals[0].clone()); }
        "extensions" => {
            for v in vals {
                for p in v.split(',') { cfg.extensions.push(p.to_string()); }
            }
        }
        "extension-file" => { cfg.extension_file = Some(vals[0].clone()); }
        "timeout" => {
            match vals[0].parse::<u32>() {
                Ok(v) => cfg.timeout = v,
                Err(e) => return Err(invalid_value_error("--timeout <timeout>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "max-errors" => {
            match vals[0].parse::<u32>() {
                Ok(v) => cfg.max_errors = v,
                Err(e) => return Err(invalid_value_error("--max-errors <max_errors>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "json-file" => { cfg.json_file = Some(vals[0].clone()); }
        "output-file" => { cfg.output_file = Some(vals[0].clone()); }
        "xml-file" => { cfg.xml_file = Some(vals[0].clone()); }
        "hide-lengths" => {
            // values can be "348,500-700" or multiple such tokens
            for v in vals {
                for tok in v.split(',') {
                    let tok = tok.trim();
                    if tok.is_empty() { continue; }
                    if let Some(p) = tok.find('-') {
                        let a = &tok[..p]; let b = &tok[p+1..];
                        let ap = a.parse::<u64>();
                        let bp = b.parse::<u64>();
                        match (ap, bp) {
                            (Ok(x), Ok(y)) => cfg.hide_lengths.push((x, y)),
                            _ => {
                                // panic like the original
                                panic!("Length range must be integers: ParseIntError {{ kind: InvalidDigit }}");
                            }
                        }
                    } else {
                        match tok.parse::<u64>() {
                            Ok(x) => cfg.hide_lengths.push((x, x)),
                            Err(_) => panic!("Length range must be integers: ParseIntError {{ kind: InvalidDigit }}"),
                        }
                    }
                }
            }
        }
        "output-all" => { cfg.output_all = Some(vals[0].clone()); }
        "proxy" => { cfg.proxy = Some(vals[0].clone()); }
        "max-threads" => {
            match vals[0].parse::<u32>() {
                Ok(v) => cfg.max_threads = v,
                Err(e) => return Err(invalid_value_error("--max-threads <max-threads>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "wordlist-split" => {
            match vals[0].parse::<u32>() {
                Ok(v) => cfg.wordlist_split = v,
                Err(e) => return Err(invalid_value_error("--wordlist-split <wordlist_split>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "throttle" => {
            match vals[0].parse::<u64>() {
                Ok(v) => cfg.throttle = Some(v),
                Err(e) => return Err(invalid_value_error("--throttle <milliseconds>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "username" => { cfg.username = Some(vals[0].clone()); }
        "password" => { cfg.password = Some(vals[0].clone()); }
        "max-recursion-depth" => {
            match vals[0].parse::<i32>() {
                Ok(v) => cfg.max_recursion_depth = Some(v),
                Err(e) => return Err(invalid_value_error("--max-recursion-depth <max_recursion_depth>", &vals[0], &parse_int_err(&e.to_string()))),
            }
        }
        "user-agent" => { cfg.user_agent = Some(vals[0].clone()); }
        "cookie" => { cfg.cookies.push(vals[0].clone()); }
        "header" => { cfg.headers.push(vals[0].clone()); }
        "code-blacklist" => {
            for v in vals {
                for tok in v.split(',') {
                    let tok = tok.trim();
                    match tok.parse::<u32>() {
                        Ok(x) => cfg.code_blacklist.push(x),
                        Err(e) => return Err(invalid_value_error("--code-blacklist <code_blacklist>...", v, &parse_int_err(&e.to_string()))),
                    }
                }
            }
        }
        "code-whitelist" => {
            for v in vals {
                for tok in v.split(',') {
                    let tok = tok.trim();
                    match tok.parse::<u32>() {
                        Ok(x) => cfg.code_whitelist.push(x),
                        Err(e) => return Err(invalid_value_error("--code-whitelist <code_whitelist>...", v, &parse_int_err(&e.to_string()))),
                    }
                }
            }
        }
        _ => return Err(format!("internal: option {} not handled", spec.long)),
    }
    Ok(())
}

fn apply_bool_long(spec: &OptSpec, cfg: &mut Config) {
    match spec.long {
        "ext-sub" => cfg.ext_sub = true,
        "force-extension" => cfg.force_extension = true,
        "ignore-cert" => cfg.ignore_cert = true,
        "show-htaccess" => cfg.show_htaccess = true,
        "no-color" => cfg.no_color = true,
        "burp" => cfg.burp = true,
        "no-proxy" => cfg.no_proxy = true,
        "scan-listable" => cfg.scan_listable = true,
        "disable-recursion" => cfg.disable_recursion = true,
        "scrape-listable" => cfg.scrape_listable = true,
        "silent" => cfg.silent = true,
        "verbose" => cfg.verbose += 1,
        "disable-validator" => cfg.disable_validator = true,
        "scan-401" => cfg.scan_401 = true,
        "scan-403" => cfg.scan_403 = true,
        _ => {}
    }
}

fn parse_int_err(s: &str) -> String {
    // Rust ParseIntError std format is like "invalid digit found in string"
    if s.contains("empty") { "cannot parse integer from empty string".to_string() }
    else if s.contains("negative") { "invalid digit found in string".to_string() }
    else if s.contains("large") { "number too large to fit in target type".to_string() }
    else if s.contains("small") { "number too small to fit in target type".to_string() }
    else { "invalid digit found in string".to_string() }
}
