pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
    pub content_len: u64,
    pub final_url: String,
}

pub struct RequestOptions {
    pub method: &'static str,
    pub timeout_secs: u64,
    pub user_agent: Option<String>,
    pub headers: Vec<String>, // raw "Header: Value" strings
    pub cookies: Vec<String>, // "name=value"
    pub basic_auth: Option<(String, String)>,
}

pub fn request(url: &Url, opts: &RequestOptions) -> Result<Response, String> {
    if url.scheme != "http" {
        return Err(format!("[1] Unsupported protocol (Scheme '{}' not supported)", url.scheme));
    }
    let host = url.host.clone();
    let port = url.port_or_default();
    let addr = format!("{}:{}", host, port);
    let addrs = addr.to_socket_addrs().map_err(|e| format!("[6] Could not resolve hostname (Could not resolve host: {}): {}", host, e))?;
    let addr = addrs.into_iter().next().ok_or_else(|| format!("[6] Could not resolve hostname"))?;
    let timeout = Duration::from_secs(opts.timeout_secs);
    let mut stream = TcpStream::connect_timeout(&addr, timeout).map_err(|e| format!("[7] Could not connect to server ({})", e))?;
    stream.set_read_timeout(Some(timeout)).map_err(|e| format!("[28] Timeout was reached ({})", e))?;
    stream.set_write_timeout(Some(timeout)).ok();

    let mut path = url.path.clone();
    if path.is_empty() { path = "/".to_string(); }
    if !url.query.is_empty() { path.push('?'); path.push_str(&url.query); }

    let mut req = String::new();
    req.push_str(&format!("{} {} HTTP/1.1\r\n", opts.method, path));
    req.push_str(&format!("Host: {}\r\n", url.host_header()));
    if let Some(ua) = &opts.user_agent { req.push_str(&format!("User-Agent: {}\r\n", ua)); }
    req.push_str("Accept: */*\r\n");
    req.push_str("Connection: close\r\n");
    if !opts.cookies.is_empty() { req.push_str(&format!("Cookie: {}\r\n", opts.cookies.join("; "))); }
    for h in &opts.headers {
        // Each header: "Header: value" or "header;"
        if let Some(p) = h.find(':') {
            req.push_str(&h[..p]); req.push_str(": "); req.push_str(h[p+1..].trim_start()); req.push_str("\r\n");
        } else if h.ends_with(';') {
            req.push_str(&h[..h.len()-1]); req.push_str(":\r\n");
        }
    }
    if let Some((u, p)) = &opts.basic_auth {
        let enc = base64_encode(format!("{}:{}", u, p).as_bytes());
        req.push_str(&format!("Authorization: Basic {}\r\n", enc));
    }
    req.push_str("\r\n");
    stream.write_all(req.as_bytes()).map_err(|e| format!("[55] Failed sending data to the peer: {}", e))?;
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).map_err(|e| format!("[28] Timeout was reached: {}", e))?;

    // Parse response
    parse_response(&buf, url)
}

fn parse_response(buf: &[u8], url: &Url) -> Result<Response, String> {
    // find end of headers
    let idx = find_crlf_crlf(buf).ok_or_else(|| "Malformed response".to_string())?;
    let hdr_bytes = &buf[..idx];
    let body = &buf[idx+4..];
    let hdr_str = String::from_utf8_lossy(hdr_bytes).to_string();
    let mut lines = hdr_str.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    // HTTP/1.1 200 OK
    let mut parts = status_line.splitn(3, ' ');
    let _proto = parts.next().unwrap_or("");
    let code = parts.next().unwrap_or("0").parse::<u16>().unwrap_or(0);
    let mut headers = Vec::new();
    for l in lines {
        if l.is_empty() { continue; }
        if let Some(p) = l.find(':') {
            headers.push((l[..p].to_string(), l[p+1..].trim_start().to_string()));
        }
    }
    // Handle chunked encoding
    let mut body_vec = body.to_vec();
    if headers.iter().any(|(n, v)| n.eq_ignore_ascii_case("Transfer-Encoding") && v.eq_ignore_ascii_case("chunked")) {
        body_vec = decode_chunked(body);
    }
    // Determine Content-Length if present
    let mut content_len = body_vec.len() as u64;
    for (n, v) in &headers {
        if n.eq_ignore_ascii_case("Content-Length") {
            if let Ok(x) = v.parse::<u64>() { content_len = x; }
        }
    }
    // If body is shorter than content-length (e.g., HEAD response), use content_len
    Ok(Response {
        status: code,
        headers,
        body: body_vec,
        content_len,
        final_url: url.to_string_norm(),
    })
}

fn find_crlf_crlf(buf: &[u8]) -> Option<usize> {
    for i in 0..buf.len().saturating_sub(3) {
        if &buf[i..i+4] == b"\r\n\r\n" { return Some(i); }
    }
    None
}

fn decode_chunked(buf: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < buf.len() {
        // Read chunk size line
        let mut j = i;
        while j + 1 < buf.len() && !(buf[j] == b'\r' && buf[j+1] == b'\n') { j += 1; }
        if j + 1 >= buf.len() { break; }
        let size_line = String::from_utf8_lossy(&buf[i..j]);
        let size_str = size_line.split(';').next().unwrap_or("").trim();
        let size = match usize::from_str_radix(size_str, 16) { Ok(s) => s, Err(_) => break };
        i = j + 2;
        if size == 0 { break; }
        if i + size > buf.len() { break; }
        out.extend_from_slice(&buf[i..i+size]);
        i += size + 2;
    }
    out
}

// Basic base64 for Authorization headers
fn base64_encode(input: &[u8]) -> String {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    let mut i = 0;
    while i + 3 <= input.len() {
        let n = ((input[i] as u32) << 16) | ((input[i+1] as u32) << 8) | (input[i+2] as u32);
        out.push(ALPHABET[((n >> 18) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 12) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 6) & 63) as usize] as char);
        out.push(ALPHABET[(n & 63) as usize] as char);
        i += 3;
    }
    let rem = input.len() - i;
    if rem == 1 {
        let n = (input[i] as u32) << 16;
        out.push(ALPHABET[((n >> 18) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 12) & 63) as usize] as char);
        out.push('=');
        out.push('=');
    } else if rem == 2 {
        let n = ((input[i] as u32) << 16) | ((input[i+1] as u32) << 8);
        out.push(ALPHABET[((n >> 18) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 12) & 63) as usize] as char);
        out.push(ALPHABET[((n >> 6) & 63) as usize] as char);
        out.push('=');
    }
    out
}
