use std::fs::File;
use std::io::Write;

use crate::scan::ScanResult;

pub fn format_console(r: &ScanResult, color: bool) -> String {
    let marker = if r.is_listable { "L" } else if r.is_directory { "D" } else { "+" };
    let url = &r.url;
    let extra = format!(" (CODE:{}|SIZE:{})", r.code, r.size);
    let redir = if !r.redirect_url.is_empty() { format!(" -> {}", r.redirect_url) } else { String::new() };
    let _ = color;
    format!("{} {}{}{}", marker, url, extra, redir)
}

pub fn write_txt(path: &str, host: &str, results: &[ScanResult]) -> std::io::Result<()> {
    let mut f = File::create(path)?;
    writeln!(f, "Dirble Scan Report for {}:", host)?;
    let mut dirs: Vec<&ScanResult> = Vec::new();
    let mut files: Vec<&ScanResult> = Vec::new();
    for r in results {
        if r.is_directory || r.is_listable { dirs.push(r); } else { files.push(r); }
    }
    for r in &files {
        let marker = "+";
        let extra = format!(" (CODE:{}|SIZE:{})", r.code, r.size);
        writeln!(f, "{} {}{}", marker, r.url, extra)?;
    }
    writeln!(f)?;
    for r in &dirs {
        let marker = if r.is_listable { "L" } else { "D" };
        let extra = format!(" (CODE:{}|SIZE:{})", r.code, r.size);
        writeln!(f, "{} {}{}", marker, r.url, extra)?;
        writeln!(f)?;
    }
    Ok(())
}

pub fn write_json(path: &str, results: &[ScanResult]) -> std::io::Result<()> {
    let mut f = File::create(path)?;
    write!(f, "[")?;
    let mut first = true;
    // Order: files first then directories (matches observed)
    let mut ordered: Vec<&ScanResult> = results.iter().filter(|r| !(r.is_directory || r.is_listable)).collect();
    let dirs: Vec<&ScanResult> = results.iter().filter(|r| r.is_directory || r.is_listable).collect();
    ordered.extend(dirs);
    for r in ordered {
        if !first { write!(f, ",\n")?; }
        first = false;
        write!(f,
            "{{\"url\":\"{}\",\"code\":{},\"size\":{},\"is_directory\":{},\"is_listable\":{},\"redirect_url\":\"{}\",\"found_from_listable\":{}}}",
            json_escape(&r.url), r.code, r.size, r.is_directory, r.is_listable, json_escape(&r.redirect_url), r.found_from_listable)?;
    }
    write!(f, "]")?;
    Ok(())
}

pub fn write_xml(path: &str, results: &[ScanResult]) -> std::io::Result<()> {
    let mut f = File::create(path)?;
    writeln!(f, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>")?;
    writeln!(f, "<dirble_scan>")?;
    let mut ordered: Vec<&ScanResult> = results.iter().filter(|r| !(r.is_directory || r.is_listable)).collect();
    let dirs: Vec<&ScanResult> = results.iter().filter(|r| r.is_directory || r.is_listable).collect();
    ordered.extend(dirs);
    for r in ordered {
        writeln!(f,
            "<path url=\"{}\" code=\"{}\" content_len=\"{}\" is_directory=\"{}\" is_listable=\"{}\" redirect_url=\"{}\" found_from_listable=\"{}\"/>",
            xml_escape(&r.url), r.code, r.size, r.is_directory, r.is_listable, xml_escape(&r.redirect_url), r.found_from_listable)?;
    }
    write!(f, "</dirble_scan>")?;
    Ok(())
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn xml_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            c => out.push(c),
        }
    }
    out
}
