use crate::args::{Config, Verb};
use crate::http::{self, RequestOptions};
use crate::url::{self, Url};
use crate::output;

#[derive(Debug, Clone)]
pub struct ScanResult {
    pub url: String,
    pub code: u16,
    pub size: u64,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

pub fn run(config: Config) -> Result<(), String> {
    // Load wordlist
    let words = crate::wordlist::load(config.wordlist.as_deref())?;

    // Build list of URIs
    let mut uris: Vec<String> = Vec::new();
    if let Some(u) = &config.uri_positional { uris.push(u.clone()); }
    for u in &config.uris { uris.push(u.clone()); }
    if let Some(file) = &config.uri_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => {
                for l in lines {
                    match url::parse(&l) {
                        Ok(_) => uris.push(l),
                        Err(_) => {
                            println!("Invalid URL: {}", l);
                        }
                    }
                }
            }
            Err(e) => return Err(e),
        }
    }

    // Build effective extensions (for directory scanning)
    let mut extensions: Vec<String> = config.extensions.clone();
    if let Some(file) = &config.extension_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => { for l in lines { extensions.push(l); } }
            Err(e) => return Err(e),
        }
    }

    let mut prefixes: Vec<String> = config.prefixes.clone();
    if let Some(file) = &config.prefix_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => { for l in lines { prefixes.push(l); } }
            Err(e) => return Err(e),
        }
    }

    let mut all_results: Vec<(String, Vec<ScanResult>)> = Vec::new();

    for uri in &uris {
        let base = match url::parse(uri) { Ok(u) => u, Err(_) => { println!("Invalid URL: {}", uri); continue; } };
        let host_key = base.to_string_with_trailing_slash();
        let mut results: Vec<ScanResult> = Vec::new();
        scan_dir(&host_key, &config, &words, &extensions, &prefixes, &mut results);
        all_results.push((host_key, results));
    }

    // Report outputs
    let mut outputs_all = Vec::new();
    if let Some(oa) = &config.output_all {
        outputs_all.push(format!("{}.txt", oa));
        outputs_all.push(format!("{}.json", oa));
        outputs_all.push(format!("{}.xml", oa));
    }

    // TXT output (--output-file, --output-all)
    let host_display = all_results.first().map(|(h, _)| h.clone()).unwrap_or_default();
    let all_flat: Vec<ScanResult> = all_results.iter().flat_map(|(_, v)| v.clone()).collect();

    if let Some(p) = &config.output_file {
        output::write_txt(p, &host_display, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_txt(&format!("{}.txt", base), &host_display, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(p) = &config.json_file {
        output::write_json(p, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_json(&format!("{}.json", base), &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(p) = &config.xml_file {
        output::write_xml(p, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_xml(&format!("{}.xml", base), &all_flat).map_err(|e| format!("{}", e))?;
    }

    Ok(())
}

fn scan_dir(dir_url: &str, config: &Config, words: &[String], extensions: &[String], prefixes: &[String], results: &mut Vec<ScanResult>) {
    // Validate: do a NotFound detection
    let base = match url::parse(dir_url) { Ok(u) => u, Err(_) => return };
    let opts = make_opts(config);

    // Determine NotFound code by requesting random URLs (simpler: just use 404 as default if disable-validator)
    let not_found_codes: Vec<u16> = if config.disable_validator || !config.code_whitelist.is_empty() {
        Vec::new()
    } else {
        detect_not_found(&base, &opts, config)
    };

    if !config.silent && !config.disable_validator && config.code_whitelist.is_empty() {
        if not_found_codes.is_empty() {
            // Could not determine; skip or continue scanning
        } else {
            let codes_str = not_found_codes.iter().map(|c| format!("CODE:{}", c)).collect::<Vec<_>>().join("|");
            println!("[INFO] Detected nonexistent paths for {} are ({})", dir_url, codes_str);
        }
    }

    // Build query list
    let mut queries: Vec<String> = Vec::new();
    for w in words {
        let mut variants: Vec<String> = Vec::new();
        variants.push(w.clone());
        // Apply prefixes
        for p in prefixes { variants.push(format!("{}{}", p, w)); }
        // Apply extensions
        let mut ext_variants = Vec::new();
        for v in &variants {
            if config.ext_sub && v.contains("%EXT%") {
                for e in extensions {
                    ext_variants.push(v.replace("%EXT%", e));
                }
                if !config.force_extension { /* skip the version with %EXT% */ }
            } else {
                if !config.force_extension { ext_variants.push(v.clone()); }
                for e in extensions { ext_variants.push(format!("{}{}", v, e)); }
            }
        }
        for q in ext_variants { queries.push(q); }
    }

    // Determine base dir
    let dir = base.to_string_with_trailing_slash();
    // Perform requests
    let mut discovered_dirs: Vec<String> = Vec::new();
    for q in &queries {
        // Build URL: dir + q (avoid double slashes)
        let mut url_str = dir.clone();
        let qstr = if q.starts_with('/') { &q[1..] } else { q.as_str() };
        url_str.push_str(qstr);
        let u = match url::parse(&url_str) { Ok(u) => u, Err(_) => continue };
        let resp = match http::request(&u, &opts) {
            Ok(r) => r,
            Err(e) => {
                if config.verbose >= 1 || !config.silent {
                    println!("Curl error after requesting {} : {}", url_str, e);
                }
                continue;
            }
        };
        let code = resp.status;
        if not_found_codes.contains(&code) { continue; }
        if !config.code_blacklist.is_empty() && config.code_blacklist.contains(&(code as u32)) { continue; }
        if !config.code_whitelist.is_empty() && !config.code_whitelist.contains(&(code as u32)) { continue; }
        let size = resp.content_len;
        // Hide lengths
        if config.hide_lengths.iter().any(|(a, b)| size >= *a && size <= *b) { continue; }
        // Filter htaccess
        if !config.show_htaccess && url_str.contains(".ht") && code == 403 { continue; }

        // Determine if directory
        let is_dir = (code == 301 || code == 302 || code == 307 || code == 308) && resp.headers.iter().any(|(n, v)| n.eq_ignore_ascii_case("Location") && v.trim_end_matches('/').ends_with(&format!("{}/", q.trim_end_matches('/'))));
        let ends_with_slash = url_str.ends_with('/');
        let mut result_is_dir = is_dir || ends_with_slash;
        let result_is_listable = false; // We don't implement scraping
        let redirect_url = if (300..400).contains(&code) {
            resp.headers.iter().find(|(n, _)| n.eq_ignore_ascii_case("Location")).map(|(_, v)| v.clone()).unwrap_or_default()
        } else { String::new() };

        let mut final_url = url_str.clone();
        if result_is_dir && !final_url.ends_with('/') { final_url.push('/'); }
        if !result_is_dir && ends_with_slash { result_is_dir = true; }

        let r = ScanResult {
            url: final_url.clone(),
            code,
            size,
            is_directory: result_is_dir,
            is_listable: result_is_listable,
            redirect_url,
            found_from_listable: false,
        };
        if !config.silent {
            let line = output::format_console(&r, !config.no_color);
            println!("{}", line);
        }
        results.push(r.clone());
        if result_is_dir && !config.disable_recursion {
            // Avoid duplicating current dir
            if final_url != dir {
                discovered_dirs.push(final_url);
            }
        }
    }
    for d in discovered_dirs {
        scan_dir(&d, config, words, extensions, prefixes, results);
    }
}

fn detect_not_found(base: &Url, opts: &RequestOptions, config: &Config) -> Vec<u16> {
    // Generate 3 random paths, see what code they return
    let mut codes = Vec::new();
    let prefix = base.to_string_with_trailing_slash();
    let random = |len: usize, seed: u64| -> String {
        let chars = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        let mut s = String::new();
        let mut x = seed;
        for _ in 0..len {
            x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let n = (x >> 33) as usize % chars.len();
            s.push(chars[n] as char);
        }
        s
    };
    let mut seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
    let mut err_count = 0;
    for i in 0..3 {
        let len = 10 + i * 10;
        seed = seed.wrapping_mul(2862933555777941757).wrapping_add(3037000493);
        let random_path = random(len, seed);
        let url_str = format!("{}{}", prefix, random_path);
        let u = match url::parse(&url_str) { Ok(u) => u, Err(_) => continue };
        match http::request(&u, opts) {
            Ok(r) => {
                if !codes.contains(&r.status) { codes.push(r.status); }
            }
            Err(e) => {
                if !config.silent {
                    println!("Curl error after requesting {} : {}", url_str, e);
                }
                err_count += 1;
            }
        }
    }
    if err_count >= 3 {
        if !config.silent {
            println!("[WARN] {} errored too often during validation, skipping scanning", prefix);
        }
        return Vec::new();
    }
    codes
}

fn make_opts(config: &Config) -> RequestOptions {
    let method: &'static str = match config.verb { Verb::Get => "GET", Verb::Head => "HEAD", Verb::Post => "POST" };
    let basic_auth = if config.username.is_some() || config.password.is_some() {
        Some((config.username.clone().unwrap_or_default(), config.password.clone().unwrap_or_default()))
    } else {
        None
    };
    RequestOptions {
        method,
        timeout_secs: config.timeout as u64,
        user_agent: config.user_agent.clone(),
        headers: config.headers.clone(),
        cookies: config.cookies.clone(),
        basic_auth,
    }
}
