        scan_dir(&d, config, words, extensions, prefixes, results);
    }
}

fn detect_not_found(base: &Url, opts: &RequestOptions, config: &Config) -> Vec<u16> {
    // Generate 3 random paths, see what code they return
    let mut codes = Vec::new();
    let prefix = base.to_string_with_trailing_slash();
    let random = |len: usize, seed: u64| -> String {
        let chars = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        let mut s = String::new();
        let mut x = seed;
        for _ in 0..len {
            x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let n = (x >> 33) as usize % chars.len();
            s.push(chars[n] as char);
        }
        s
    };
    let mut seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
    let mut err_count = 0;
    for i in 0..3 {
        let len = 10 + i * 10;
        seed = seed.wrapping_mul(2862933555777941757).wrapping_add(3037000493);
        let random_path = random(len, seed);
        let url_str = format!("{}{}", prefix, random_path);
        let u = match url::parse(&url_str) { Ok(u) => u, Err(_) => continue };
        match http::request(&u, opts) {
            Ok(r) => {
                if !codes.contains(&r.status) { codes.push(r.status); }
            }
            Err(e) => {
                if !config.silent {
                    println!("Curl error after requesting {} : {}", url_str, e);
                }
                err_count += 1;
            }
        }
    }
    if err_count >= 3 {
        if !config.silent {
            println!("[WARN] {} errored too often during validation, skipping scanning", prefix);
        }
        return Vec::new();
    }
    codes
}

fn make_opts(config: &Config) -> RequestOptions {
    let method: &'static str = match config.verb { Verb::Get => "GET", Verb::Head => "HEAD", Verb::Post => "POST" };
    let basic_auth = if config.username.is_some() || config.password.is_some() {
        Some((config.username.clone().unwrap_or_default(), config.password.clone().unwrap_or_default()))
    } else {
        None
    };
    RequestOptions {
        method,
        timeout_secs: config.timeout as u64,
        user_agent: config.user_agent.clone(),
        headers: config.headers.clone(),
        cookies: config.cookies.clone(),
        basic_auth,
    }
}
