                if after.starts_with(':') {
                    (hostport, Some(&after[1..]))
                } else if after.is_empty() {
                    (hostport, None)
                } else {
                    return Err("invalid port number".to_string());
                }
            }
            None => return Err("invalid IPv6 address".to_string()),
        }
    } else if let Some(i) = hostport.rfind(':') {
        let after = &hostport[i+1..];
        (&hostport[..i], if after.is_empty() { None } else { Some(after) })
    } else {
        (hostport, None)
    };

    let port = match port_str {
        Some(p) => {
            match p.parse::<u16>() {
                Ok(v) => Some(v),
                Err(_) => return Err("invalid port number".to_string()),
            }
        }
        None => None,
    };

    // Validate host
    if host_raw.is_empty() {
        return Err("empty host".to_string());
    }
    // Check for invalid chars in host (approximating url crate's behavior)
    for c in host_raw.chars() {
        if c.is_ascii_control() || c == ' ' || c == '<' || c == '>' || c == '|' || c == '%' || c == '\x7f' {
            return Err("invalid international domain name".to_string());
        }
    }

    let host = host_raw.to_ascii_lowercase();

    // Split tail into path, query, fragment
    let (pp, fragment) = match tail.find('#') {
        Some(i) => (tail[..i].to_string(), tail[i+1..].to_string()),
        None => (tail.to_string(), String::new()),
    };
    let (path, query) = match pp.find('?') {
        Some(i) => (pp[..i].to_string(), pp[i+1..].to_string()),
        None => (pp, String::new()),
    };
    let path = if path.is_empty() { "/".to_string() } else { path };

    Ok(Url {
        scheme,
        userinfo,
        host,
        port,
        path,
        query,
        fragment,
    })
}

impl Url {
    pub fn port_or_default(&self) -> u16 {
        match self.port {
            Some(p) => p,
            None => match self.scheme.as_str() {
                "https" => 443,
                "http" => 80,
                _ => 80,
            },
        }
    }

    pub fn host_header(&self) -> String {
        match self.port {
            Some(p) => format!("{}:{}", self.host, p),
            None => self.host.clone(),
        }
    }

    pub fn base(&self) -> String {
        let mut s = format!("{}://{}", self.scheme, self.host);
        if let Some(p) = self.port {
            s.push_str(&format!(":{}", p));
        }
        s
    }

    pub fn to_string_with_trailing_slash(&self) -> String {
        let mut s = self.base();
        let mut p = self.path.clone();
        if !p.ends_with('/') {
            p.push('/');
        }
        s.push_str(&p);
        s
    }

    pub fn to_string_norm(&self) -> String {
        let mut s = self.base();
        if self.path.is_empty() {
            s.push('/');
        } else {
            s.push_str(&self.path);
        }
        s
    }
}
