use crate::args::{Config, Verb};
use crate::http::{self, RequestOptions};
use crate::url::{self, Url};
use crate::output;

#[derive(Debug, Clone)]
pub struct ScanResult {
    pub url: String,
    pub code: u16,
    pub size: u64,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
}

pub fn run(config: Config) -> Result<(), String> {
    let words = crate::wordlist::load(config.wordlist.as_deref())?;

    let mut uris: Vec<String> = Vec::new();
    if let Some(u) = &config.uri_positional { uris.push(u.clone()); }
    for u in &config.uris { uris.push(u.clone()); }
    if let Some(file) = &config.uri_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => {
                for l in lines {
                    match url::parse(&l) {
                        Ok(_) => uris.push(l),
                        Err(_) => println!("Invalid URL: {}", l),
                    }
                }
            }
            Err(e) => return Err(e),
        }
    }

    let mut extensions: Vec<String> = config.extensions.clone();
    if let Some(file) = &config.extension_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => { for l in lines { extensions.push(l); } }
            Err(e) => return Err(e),
        }
    }

    let mut prefixes: Vec<String> = config.prefixes.clone();
    if let Some(file) = &config.prefix_file {
        match crate::wordlist::load_lines(file) {
            Ok(lines) => { for l in lines { prefixes.push(l); } }
            Err(e) => return Err(e),
        }
    }

    let mut all_results: Vec<(String, Vec<ScanResult>)> = Vec::new();

    for uri in &uris {
        let base = match url::parse(uri) { Ok(u) => u, Err(_) => { println!("Invalid URL: {}", uri); continue; } };
        let host_key = base.to_string_with_trailing_slash();
        let mut results: Vec<ScanResult> = Vec::new();
        scan_dir(&host_key, &config, &words, &extensions, &prefixes, &mut results, 0);
        all_results.push((host_key, results));
    }

    let host_display = all_results.first().map(|(h, _)| h.clone()).unwrap_or_default();
    let all_flat: Vec<ScanResult> = all_results.iter().flat_map(|(_, v)| v.clone()).collect();

    if let Some(p) = &config.output_file {
        output::write_txt(p, &host_display, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_txt(&format!("{}.txt", base), &host_display, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(p) = &config.json_file {
        output::write_json(p, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_json(&format!("{}.json", base), &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(p) = &config.xml_file {
        output::write_xml(p, &all_flat).map_err(|e| format!("{}", e))?;
    }
    if let Some(base) = &config.output_all {
        output::write_xml(&format!("{}.xml", base), &all_flat).map_err(|e| format!("{}", e))?;
    }

    Ok(())
}

fn scan_dir(dir_url: &str, config: &Config, words: &[String], extensions: &[String], prefixes: &[String], results: &mut Vec<ScanResult>, depth: u32) {
    let max_depth = match config.max_recursion_depth { Some(v) if v >= 0 => v as u32, _ => u32::MAX };
    if depth > max_depth { return; }
    let base = match url::parse(dir_url) { Ok(u) => u, Err(_) => return };
    let opts = make_opts(config);

    let not_found_codes: Vec<u16> = if config.disable_validator || !config.code_whitelist.is_empty() {
        Vec::new()
    } else {
        detect_not_found(&base, &opts, config)
    };

    if !config.silent && !config.disable_validator && config.code_whitelist.is_empty() {
        if !not_found_codes.is_empty() {
            let codes_str = not_found_codes.iter().map(|c| format!("CODE:{}", c)).collect::<Vec<_>>().join("|");
            println!("[INFO] Detected nonexistent paths for {} are ({})", dir_url, codes_str);
        }
    }

    // Build query list
    let mut queries: Vec<String> = Vec::new();
    for w in words {
        let mut variants: Vec<String> = Vec::new();
        variants.push(w.clone());
        for p in prefixes { variants.push(format!("{}{}", p, w)); }
        let mut ext_variants = Vec::new();
        for v in &variants {
            if config.ext_sub && v.contains("%EXT%") {
                for e in extensions { ext_variants.push(v.replace("%EXT%", e)); }
            } else {
                if !config.force_extension { ext_variants.push(v.clone()); }
                for e in extensions { ext_variants.push(format!("{}{}", v, e)); }
            }
        }
        for q in ext_variants { queries.push(q); }
    }

    let dir = base.to_string_with_trailing_slash();
    let mut discovered_dirs: Vec<String> = Vec::new();
    for q in &queries {
        let mut url_str = dir.clone();
