        let resp = match http::request(&u, &opts) {
            Ok(r) => r,
            Err(e) => {
                if !config.silent {
                    println!("Curl error after requesting {} : {}", url_str, e);
                }
                continue;
            }
        };
        let mut code = resp.status;

        // Check if this is a redirect indicating a directory (/path/ style)
        let mut is_directory = false;
        let mut final_url = url_str.clone();
        let mut size = resp.content_len;
        let mut redirect_url = String::new();

        if (300..400).contains(&code) {
            if let Some((_, loc)) = resp.headers.iter().find(|(n, _)| n.eq_ignore_ascii_case("Location")) {
                redirect_url = loc.clone();
