                let expected_dir = format!("{}/", u.to_string_norm());
                let loc_full = resolve_url(&u, loc);
                if loc_full == expected_dir || loc.trim_end_matches('/').ends_with(&format!("{}/", q.trim_end_matches('/'))) {
                    // It's a directory redirect; fetch the / version
                    let dir_url_str = format!("{}/", url_str.trim_end_matches('/'));
                    let du = match url::parse(&dir_url_str) { Ok(u) => u, Err(_) => u.clone() };
                    match http::request(&du, &opts) {
                        Ok(r2) => {
                            code = r2.status;
                            size = r2.content_len;
                            final_url = dir_url_str;
                            is_directory = true;
                            redirect_url = String::new();
                        }
                        Err(_) => {}
                    }
                }
            }
        }

        if !is_directory && url_str.ends_with('/') { is_directory = true; }

        if not_found_codes.contains(&code) { continue; }
        if !config.code_blacklist.is_empty() && config.code_blacklist.contains(&(code as u32)) { continue; }
