        results.push(r.clone());
        if is_directory && !config.disable_recursion {
            if final_url != dir { discovered_dirs.push(final_url); }
        }
    }
    for d in discovered_dirs {
        scan_dir(&d, config, words, extensions, prefixes, results, depth + 1);
    }
}

